SELECT allocation.allocation_id, allocation.account_id, allocation.statement_id, allocation.transaction_id AS payment_id, selected.transaction_id AS batch_id, CASE WHEN (allocation.total_payment - allocation.minimum_payment_portion) IS NULL THEN (selected.amount) WHEN (selected.amount) IS NULL THEN (allocation.total_payment - allocation.minimum_payment_portion) ELSE MIN(allocation.total_payment - allocation.minimum_payment_portion, selected.amount) END AS proposed_cash_dollars
FROM payment_allocations AS allocation CROSS JOIN transactions AS selected
WHERE allocation.allocation_id = 'ALLOC0000003' AND allocation.account_id = selected.account_id AND selected.transaction_id = (SELECT candidate.transaction_id FROM transactions AS candidate JOIN daily_balances AS balance ON balance.account_id = candidate.account_id AND balance.statement_id = candidate.statement_id AND balance.balance_category = candidate.balance_category WHERE candidate.account_id = allocation.account_id AND candidate.statement_id = allocation.statement_id AND candidate.transaction_type = 'cash_advance' AND balance.balance_date = DATE('2027-04-02') ORDER BY balance.apr_applied DESC LIMIT 1);
